"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def SearchRotatedArray(arr, target):
    low = 0
    high = (len(arr) - 1)
    while (low <= high):
        mid = (low + ((high - low) // 2))
        if (arr[mid] == target):
            return mid
            # Left side is sorted
        if (arr[low] <= arr[mid]):
            if ((arr[low] <= target) and (target < arr[mid])):
                high = (mid - 1)
            else:
                low = (mid + 1)
            # Right side is sorted
        else:
            if ((arr[mid] < target) and (target <= arr[high])):
                low = (mid + 1)
            else:
                high = (mid - 1)
    return (-1)


print(SearchRotatedArray([4, 5, 6, 7, 0, 1, 2], 0))